"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["95930"],{92088(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modalidade.ampla_concorrencia_com_condicao","status":422,"titulo":"A ampla concorr\xeancia vale para todo candidato e n\xe3o admite condi\xe7\xe3o"},"descricao":{"codigo":"uniplus.configuracao.modalidade.ampla_concorrencia_com_condicao","requisitos":["UNI-REQ-0076","UNI-REQ-0141"],"oQueAconteceu":["A modalidade tem natureza **ampla concorr\xeancia** (`AMPLA`, que \xe9 o valor assumido quando `naturezaLegal` \xe9 omitida) e, ainda assim, traz cl\xe1usulas em `regraDeAplicabilidade`. A ampla concorr\xeancia vale para todo candidato: toda pessoa inscrita concorre a ela, e por isso ela n\xe3o pode filtrar ningu\xe9m. Nada foi gravado.","Na atualiza\xe7\xe3o, a modalidade \xe9 procurada antes desta confer\xeancia: com um identificador inexistente a resposta \xe9 [modalidade n\xe3o encontrada](/erros/uniplus.configuracao.modalidade.nao_encontrada), mesmo que o conte\xfado enviado tamb\xe9m tivesse este problema. Numa modalidade do cat\xe1logo legal fixo esta recusa n\xe3o \xe9 emitida: se o conte\xfado altera algo al\xe9m da descri\xe7\xe3o e da base legal, vale [estrutura protegida n\xe3o edit\xe1vel](/erros/uniplus.configuracao.modalidade.estrutura_protegida_nao_editavel)."],"comoResolver":["Envie `regraDeAplicabilidade` como `[]` na ampla concorr\xeancia. Se a modalidade deve valer s\xf3 para um grupo de candidatos, ela n\xe3o \xe9 ampla concorr\xeancia: ajuste `naturezaLegal` para a natureza correta."],"ondeAparece":["Cria\xe7\xe3o de uma modalidade (POST /api/configuracao/admin/modalidades)","Atualiza\xe7\xe3o de uma modalidade fora do cat\xe1logo legal fixo (PUT /api/configuracao/admin/modalidades/`{id}`), depois de a modalidade ser encontrada"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modalidade"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);